using System;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;

internal sealed class DpsSkillsPane:Grid {
    readonly EnergyOverlay owner;readonly TextBlock status=SettingsVisual.Text("",11,"#8994A6");readonly DataGrid table=new DataGrid{AutoGenerateColumns=false,IsReadOnly=true,CanUserAddRows=false,CanUserDeleteRows=false,EnableRowVirtualization=true,EnableColumnVirtualization=true,HeadersVisibility=DataGridHeadersVisibility.Column,RowHeaderWidth=0,MinHeight=190};
    long revision=-1;string language;
    internal DpsSkillsPane(EnergyOverlay parent){owner=parent;RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});var header=new StackPanel{Margin=new Thickness(0,4,0,12)};header.Children.Add(SettingsVisual.Text("Skill breakdown",16));header.Children.Add(SettingsVisual.Text("Live skill totals by player and target. Unknown names keep their damage; the catalogue updates labels without resetting the fight.",11,"#8994A6"));status.Margin=new Thickness(0,8,0,0);header.Children.Add(status);Children.Add(header);Grid.SetRow(table,1);Children.Add(table);}
    void Columns(){table.Columns.Clear();Add("Name","Player",130);Add("Skill","Skill",210);Add("Damage","Damage",110);Add("Healing done","Healing",110);Add("Healing received","HealingReceived",115);Add("Periodic damage","PeriodicDamage",120);Add("Highest hit","HighestHit",100);Add("Skill ID","SkillId",95);Add("Target ID","TargetId",85);Add("Direct impacts","DirectImpacts",110);Add("Periodic ticks","PeriodicTicks",110);Add("Damage crit. rate","CriticalRate",115,"{0:0.0}%");Add("Damage crit. %","CriticalShare",110,"{0:0.0}%");Add("Healing crit. rate","HealingCriticalRate",115,"{0:0.0}%");Add("Healing crit. %","HealingCriticalShare",110,"{0:0.0}%");Add("Received crit. rate","ReceivedCriticalRate",115,"{0:0.0}%");Add("Received crit. %","ReceivedCriticalShare",110,"{0:0.0}%");}
    void Add(string title,string field,double width,string format=null){var binding=new Binding(field);if(format!=null)binding.StringFormat=format;table.Columns.Add(new DataGridTextColumn{Header=UiLanguage.Text(title,owner.Language),Binding=binding,Width=width});}
    internal void Refresh(bool force=false){if(!force&&!IsVisible)return;long current=owner.CombatSkillRevision;if(force||language!=owner.Language){language=owner.Language;Columns();UiLanguage.Apply(this,language);revision=-1;}string text=owner.SkillCatalogueStatus;if(status.Text!=text)status.Text=text;if(force||revision!=current){revision=current;table.ItemsSource=owner.CombatSkills;}}
    internal static DataGrid HistoryTable(string language){var t=new DataGrid{AutoGenerateColumns=false,IsReadOnly=true,CanUserAddRows=false,CanUserDeleteRows=false,EnableRowVirtualization=true,EnableColumnVirtualization=true,HeadersVisibility=DataGridHeadersVisibility.Column,Height=200,RowHeaderWidth=0};ConfigureHistory(t,language);return t;}
    internal static void ConfigureHistory(DataGrid t,string language){t.Columns.Clear();foreach(var pair in new[]{new[]{"Name","Player"},new[]{"Skill","Skill"},new[]{"Skill ID","SkillId"},new[]{"Target ID","TargetId"},new[]{"Damage","Damage"},new[]{"Periodic damage","PeriodicDamage"},new[]{"Healing done","Healing"},new[]{"Healing received","HealingReceived"},new[]{"Highest hit","HighestHit"},new[]{"Direct impacts","DirectImpacts"},new[]{"Periodic ticks","PeriodicTicks"}})t.Columns.Add(new DataGridTextColumn{Header=UiLanguage.Text(pair[0],language),Binding=new Binding(pair[1]),Width=pair[1]=="Skill"?210:115});}
}
